/**
 * Headless Chrome responsive gate for the Agent Governance fixtures.
 * Requires the fixtures generated by generate-governance-fixtures.ts.
 *
 * Usage (Node 20):
 *   CHROME_BIN="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" \
 *   node scripts/governance-viewport-check.mjs [--screenshots]
 *
 * Verifies at 720x520, 1024x720 and 1440x900 that:
 *   documentElement.scrollWidth <= clientWidth
 *   governance root scrollWidth <= clientWidth
 *   governance workspace scrollWidth <= clientWidth
 *   no element has recoverable-unclipped horizontal overflow
 */
import { spawnSync } from "node:child_process";
import { mkdirSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const appRoot = resolve(here, "..");
const fixturesRoot = resolve(appRoot, "../../tmp/runtime/agent-governance-interface-simplification/fixtures");
const outputRoot = resolve(appRoot, "../../tmp/runtime/agent-governance-interface-simplification");
const chrome = process.env.CHROME_BIN ?? "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const viewports = [
  { width: 720, height: 520 },
  { width: 1024, height: 720 },
  { width: 1440, height: 900 },
];

const files = readdirSync(fixturesRoot).filter((name) => name.endsWith(".html")).sort();
const report = { chrome, viewports, checks: [], failures: [] };

function runChrome(args) {
  const result = spawnSync(chrome, args, { encoding: "utf8", maxBuffer: 16 * 1024 * 1024 });
  if (result.status !== 0) {
    throw new Error(`Chrome exited ${result.status}: ${result.stderr.slice(0, 800)}`);
  }
  return result.stdout;
}

function parseMetrics(stdout) {
  const match = stdout.match(/<pre id="agi-metrics">([\s\S]*?)<\/pre>/);
  if (!match) throw new Error("fixture metrics element missing");
  return JSON.parse(match[1]);
}

for (const file of files) {
  const fixture = join(fixturesRoot, file);
  const theme = file.includes("-dark") ? "dark" : "light";
  for (const viewport of viewports) {
    const stdout = runChrome([
      "--headless=new",
      "--disable-gpu",
      "--no-first-run",
      "--enable-features=OverlayScrollbar",
      "--virtual-time-budget=400",
      `--window-size=${viewport.width},${viewport.height}`,
      "--dump-dom",
      `file://${fixture}`,
    ]);
    const metrics = parseMetrics(stdout);
    const failures = [];
    if (metrics.docScrollWidth > metrics.docClientWidth) failures.push(`document ${metrics.docScrollWidth} > ${metrics.docClientWidth}`);
    if (metrics.rootScrollWidth > metrics.rootClientWidth) failures.push(`root ${metrics.rootScrollWidth} > ${metrics.rootClientWidth}`);
    if (metrics.workspaceScrollWidth > metrics.workspaceClientWidth) failures.push(`workspace ${metrics.workspaceScrollWidth} > ${metrics.workspaceClientWidth}`);
    if (metrics.horizontalOverflowCount > 0) failures.push(`overflowing elements ${metrics.horizontalOverflowCount}`);
    const entry = { fixture: file, theme, viewport, metrics, pass: failures.length === 0 };
    report.checks.push(entry);
    if (failures.length) report.failures.push({ fixture: file, viewport, failures });
  }
}

const screenshots = process.argv.includes("--screenshots");
if (screenshots) {
  const shotRoot = join(outputRoot, "screenshots");
  mkdirSync(shotRoot, { recursive: true });
  const normal = { width: 1440, height: 900 };
  const narrow = { width: 720, height: 520 };
  const targetSets = [
    ...files.map((file) => ({ file, viewport: normal })),
    ...files.filter((file) => file.includes("-light")).map((file) => ({ file, viewport: narrow })),
  ];
  for (const { file, viewport } of targetSets) {
    const out = join(shotRoot, `${file.replace(/\.html$/, "")}-${viewport.width}x${viewport.height}.png`);
    runChrome([
      "--headless=new",
      "--disable-gpu",
      "--no-first-run",
      "--enable-features=OverlayScrollbar",
      "--virtual-time-budget=400",
      "--hide-scrollbars",
      `--window-size=${viewport.width},${viewport.height}`,
      `--screenshot=${out}`,
      `file://${join(fixturesRoot, file)}`,
    ]);
  }
  report.screenshotCount = targetSets.length;
  report.screenshotRoot = shotRoot;
}

writeFileSync(join(outputRoot, "viewport-report.json"), `${JSON.stringify(report, null, 2)}\n`);
console.log(`Checks: ${report.checks.length}, failures: ${report.failures.length}${screenshots ? `, screenshots: ${report.screenshotCount}` : ""}`);
if (report.failures.length) {
  console.error(JSON.stringify(report.failures, null, 2));
  process.exit(1);
}
